def count_char_categories(s):
    d = {"digits": 0, "letters": 0, "spaces": 0, "other": 0}
    for ch in s:
        if ch.isdigit():
            d["digits"] += 1
        elif ch.isalpha():
            d["letters"] += 1
        elif ch.isspace():
            d["spaces"] += 1
        else:
            d["other"] += 1
    return d

def count_repeating_unit_repeats(s):
    n = len(s)
    if n == 0:
        return 0
    for length in range(1, n):
        if n % length == 0:
            unit = s[:length]
            if unit * (n // length) == s:
                return n // length
    return 1

