def prime_gap(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    primes = []
    cand = 2
    while len(primes) < n + 1:
        if is_prime(cand):
            primes.append(cand)
        cand += 1
    return primes[n] - primes[n - 1]

def smallest_number_with_digit_sum(s, d):
    if s < 1 or s > 9 * d:
        return -1
    digits = [0] * d
    remaining = s
    for i in range(d - 1, 0, -1):
        take = min(9, remaining)
        if remaining - take < 1:
            take = remaining - 1
        digits[i] = take
        remaining -= take
    digits[0] = remaining
    return int(''.join(map(str, digits)))

